def ajouter_bonus(notes, bonus):
    for indice in range(len(notes)):
        notes[indice] = notes[indice] + bonus
    return notes

def modifier_quantite(stock, code, nouvelle):
    resultat = stock.copy()
    for fiche in resultat:
        if fiche["code"] == code:
            fiche["quantite"] = nouvelle
    return resultat

exercises.solution:
def modifier_quantite(stock, code, nouvelle):
    resultat = [fiche.copy() for fiche in stock]
    for fiche in resultat:
        if fiche["code"] == code:
            fiche["quantite"] = nouvelle
    return resultat

def attribuer_materiel(groupes, nom, objet):
    resultat = []
    for groupe in groupes:
        copie = groupe.copy()
        copie["materiel"] = list(groupe["materiel"])
        if groupe["nom"] == nom:
            copie["materiel"].append(objet)
        resultat.append(copie)
    return resultat
